        code.Append(" public static Sprite Carry(bool twoHand,int d,int v,out Vector2 h,out bool b)=>Pick(0,twoHand?1:0,d,v,0,out h,out b);\n public static Sprite Melee(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(1,c,d,v,k,out h,out b);\n public static Sprite Short(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(2,c,d,v,k,out h,out b);\n public static Sprite Thrust(int d,int gait,int k,out Vector2 h){bool b;return Pick(3,0,d,gait+1,k,out h,out b);}\n public static Sprite Defense(int c,int d,int v,int k,out Vector2 h,out bool b)=>c==3&&k==0?Pick(4,2,d,v,15,out h,out b):Pick(4,c,d,v,k,out h,out b);\n public static Sprite Ranged(int c,int d,int v,int k,out Vector2 h,out bool b)=>Pick(5,c,d,v,k,out h,out b);\n }\n}\n");
